mapper.update:
UPDATE plan_usage_counter
SET used_count = used_count + 1, updated_at = #{now}
WHERE account_id = #{accountId} AND feature = #{feature} AND period_key = #{periodKey}
  AND used_count < #{limit}

UPDATE plan_usage_counter
SET used_count = used_count - 1, updated_at = #{now}
WHERE account_id = #{accountId} AND feature = #{feature} AND period_key = #{periodKey}
  AND used_count > 0

mapper.insert:
INSERT INTO plan_usage_counter (account_id, feature, period_key, used_count, updated_at)
VALUES (#{accountId}, #{feature}, #{periodKey}, #{amount}, #{now})
ON DUPLICATE KEY UPDATE used_count = used_count + #{amount}, updated_at = #{now}

mapper.select:
SELECT feature, period_key, used_count
FROM plan_usage_counter
WHERE account_id = #{accountId}
  AND period_key IN
#{periodKey}

SELECT COUNT(*)
FROM combination_review_run r
INNER JOIN combination_review c ON c.id = r.review_id
WHERE c.owner_account_id = #{accountId}
  AND c.demo_seed_key IS NULL
  AND r.started_at >= #{from} AND r.started_at < #{to}
  AND r.status IN ('QUEUED', 'RUNNING', 'UNKNOWN', 'SUCCEEDED')
AND r.id <> #{excludeRunId}

SELECT COUNT(*) FROM (
    SELECT d.source_code COLLATE utf8mb4_0900_bin AS source_code,
           d.source_program_id COLLATE utf8mb4_0900_bin AS source_program_id
    FROM application_form_discovery_job d
    WHERE d.owner_account_id = #{accountId}
      AND d.created_at >= #{from} AND d.created_at < #{to}
      AND d.status IN ('QUEUED', 'RUNNING', 'UNKNOWN', 'SUCCEEDED')
    AND d.id <> #{excludeDiscoveryJobId}
    UNION
    SELECT p.source_code, p.source_program_id
    FROM application_document_generation_job j
    INNER JOIN application_preparation p ON p.id = j.preparation_id
    WHERE j.owner_account_id = #{accountId}
      AND p.demo_seed_key IS NULL
      AND j.created_at >= #{from} AND j.created_at < #{to}
      AND j.status IN ('QUEUED', 'RUNNING', 'UNKNOWN', 'SUCCEEDED')
    AND j.id <> #{excludeGenerationJobId}
    UNION
    SELECT p.source_code, p.source_program_id
    FROM application_document_file f
    INNER JOIN application_preparation p ON p.id = f.preparation_id
    WHERE p.owner_account_id = #{accountId}
      AND p.demo_seed_key IS NULL
      AND f.created_at >= #{from} AND f.created_at < #{to}
    UNION
    SELECT p.source_code, p.source_program_id
    FROM application_preparation_interpretation_run i
    INNER JOIN application_preparation p ON p.id = i.preparation_id
    WHERE p.owner_account_id = #{accountId}
      AND p.demo_seed_key IS NULL
      AND i.started_at >= #{from} AND i.started_at < #{to}
      AND i.run_status IN ('RUNNING', 'SUCCEEDED')
    UNION
    SELECT p.source_code, p.source_program_id
    FROM application_preparation_draft_run r
    INNER JOIN application_preparation p ON p.id = r.preparation_id
    WHERE p.owner_account_id = #{accountId}
      AND p.demo_seed_key IS NULL
      AND r.started_at >= #{from} AND r.started_at < #{to}
      AND r.run_status IN ('RUNNING', 'SUCCEEDED')

    UNION
    SELECT #{includeSourceCode} COLLATE utf8mb4_0900_bin, #{includeSourceProgramId} COLLATE utf8mb4_0900_bin

) programs

SELECT COUNT(*)
FROM partner_proposal
WHERE proposer_account_id = #{accountId}
  AND created_at >= #{from} AND created_at < #{to}
AND id <> #{excludeProposalId}

SELECT program.application_period_raw, program.application_start_date, program.application_end_date
FROM partner_recruitment recruitment
INNER JOIN support_program program ON program.id = recruitment.support_program_id
WHERE recruitment.account_id = #{accountId}
  AND recruitment.closed_at IS NULL
  AND recruitment.recruitment_deadline >= #{today}
